import type { PostApi, PostDto, PostValues, ServerIssue } from './domain';
import type { RuleFor, Save, FieldIssue } from '@zxio/schema-form/form-create';
export function createPostRules():RuleFor<PostValues>[] {
 return [
 {type:'ZxInput',field:'postName',validate:[{required:true,whitespace:true,max:50}],},
 {type:'ZxInput',field:'postCode',validate:[{required:true,whitespace:true,max:64}],},
 {type:'ZxInputNumber',field:'postSort',validate:[{required:true,type:'integer',min:0}],},
 {type:'ZxRadioGroup',field:'status',validate:[{required:true,type:'enum',enum:['0','1']}],},
 {type:'ZxInput',field:'remark',props:{type:'textarea'},fullWidth:true}
 ]
}
export function toPostDto(values:unknown,postId?:number):PostDto {
 if (!values || typeof values!=='object') throw new Error('bad');
 if (!('postName' in values) || !('postCode' in values) || !('postSort' in values) || !('status' in values) || !('remark' in values)) throw new Error('bad');
 const {postName,postCode,postSort,status,remark}=values;
 if (typeof postName!=='string'||!postName.trim()||postName.length>50||typeof postCode!=='string'||!postCode.trim()||postCode.length>64||typeof postSort!=='number'||!Number.isInteger(postSort)||postSort<0||(status!=='0'&&status!=='1')||typeof remark!=='string') throw new Error('bad');
 return {postName,postCode,postSort,status,remark,...(postId===undefined?{}:{postId})};
}
export function postFieldIssues(errors:readonly ServerIssue[]):FieldIssue[] {
 const fields:Record<string,string>={post_name:'postName',post_code:'postCode',post_sort:'postSort',status:'status',remark:'remark'};
 return errors.map(e=>({message:e.message,path:Object.hasOwn(fields,e.field)?[fields[e.field]]:undefined}));
}
export function createPostSave(api:PostApi,postId?:number):Save<PostValues> {
 return async(values,signal)=>{const result=await api.write(toPostDto(values,postId),signal); return result.ok?{ok:true}:{ok:false,issues:postFieldIssues(result.errors)}};
}
